// Expression describes a Go type expression as seen in source.
type Expression struct {
	Value      string
	IsStar     bool
	IsVariadic bool
	IsWriter   bool
	Underlying string
}

// String renders the expression as it should appear in generated code.
func (e *Expression) String() string {
	v := e.Value
	if e.IsStar {
		v = "*" + v
	}
	if e.IsVariadic {
		return "[]" + v
	}
	return v
}

// IsBasicType reports whether the expression (or its underlying type)
// denotes one of Go's predeclared basic types.
func (e *Expression) IsBasicType() bool {
	return basicType(e.Value) || basicType(e.Underlying)
}

func basicType(s string) bool {
	switch s {
	case "bool", "string",
		"int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64", "uintptr",
		"byte", "rune",
		"float32", "float64",
		"complex64", "complex128":
		return true
	}
	return false
}

// Field is a named (or anonymous) element of a parameter list, result
// list or struct declaration.
type Field struct {
	Name  string
	Type  *Expression
	Index int
}

// IsWriter reports whether the field's type is io.Writer.
func (f *Field) IsWriter() bool { return f.Type.IsWriter }

// IsStruct reports whether the underlying type of the field is a struct.
func (f *Field) IsStruct() bool { return strings.HasPrefix(f.Type.Underlying, "struct") }

// IsBasicType reports whether the field type is a basic type.
func (f *Field) IsBasicType() bool { return f.Type.IsBasicType() }

// IsNamed reports whether the field carries a usable name.
func (f *Field) IsNamed() bool { return f.Name != "" && f.Name != "_" }

// ShortName derives a one letter identifier from the type name.
func (f *Field) ShortName() string {
	r := []rune(f.Type.Value)
	if len(r) == 0 {
		return ""
	}
	return strings.ToLower(string(r[0]))
}

// Receiver is a method receiver together with the struct fields of its
// type (when the type is a struct).
type Receiver struct {
	*Field
	Fields []*Field
}

// TypeParam is a single type parameter of a generic declaration.
type TypeParam struct {
	Name       string
	Constraint string
}

// Function describes a function or method declaration.
type Function struct {
	Name         string
	IsExported   bool
	Receiver     *Receiver
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
	TypeParams   []*TypeParam
	Body         string
}

// TestParameters are the parameters that become part of the args struct
// (io.Writer parameters are handled separately).
func (f *Function) TestParameters() []*Field {
	var out []*Field
	for _, p := range f.Parameters {
		if p.IsWriter() {
			continue
		}
		out = append(out, p)
	}
	return out
}

// TestResults are the results plus a synthetic string result for every
// io.Writer parameter.
func (f *Function) TestResults() []*Field {
	var out []*Field
	out = append(out, f.Results...)
	for _, p := range f.Parameters {
		if !p.IsWriter() {
			continue
		}
		out = append(out, &Field{
			Name: p.Name,
			Type: &Expression{
				Value:      "string",
				IsWriter:   true,
				Underlying: "string",
			},
			Index: len(out),
		})
	}
	return out
}

// ReturnsMultiple reports whether more than one non-error value is returned.
func (f *Function) ReturnsMultiple() bool { return len(f.Results) > 1 }

// OnlyReturnsOneValue reports whether exactly one non-error value and no
// error is returned.
func (f *Function) OnlyReturnsOneValue() bool { return len(f.Results) == 1 && !f.ReturnsError }

// OnlyReturnsError reports whether the only result is an error.
func (f *Function) OnlyReturnsError() bool { return len(f.Results) == 0 && f.ReturnsError }

// FullName is the receiver type name joined with the function name, both
// title-cased.
func (f *Function) FullName() string {
	var recv string
	if f.Receiver != nil {
		recv = f.Receiver.Type.Value
	}
	return title(recv) + title(f.Name)
}

// TestName is the name of the generated test function.
func (f *Function) TestName() string {
	if f.Receiver != nil {
		recv := f.Receiver.Type.Value
		if i := strings.Index(recv, "["); i >= 0 {
			recv = recv[:i]
		}
		if startsLower(recv) {
			recv = "_" + recv
		}
		return "Test" + recv + "_" + f.Name
	}
	if startsLower(f.Name) {
		return "Test_" + f.Name
	}
	return "Test" + f.Name
}

// IsNaked reports whether the function has no receiver, parameters or
// (non-error) results.
func (f *Function) IsNaked() bool {
	return f.Receiver == nil && len(f.Parameters) == 0 && len(f.Results) == 0
}

func startsLower(s string) bool {
	r := []rune(s)
	return len(r) > 0 && unicode.IsLower(r[0])
}

func title(s string) string {
	r := []rune(s)
	if len(r) == 0 {
		return s
	}
	r[0] = unicode.ToTitle(r[0])
	return string(r)
}

// Import is a single import spec of a Go file.
type Import struct {
	Name string
	Path string
}

// Header is everything of a Go file that precedes the declarations.
type Header struct {
	Comments []string
	Package  string
	Imports  []*Import
	Code     []byte
}

// Path is a file system path to a Go source or test file.
type Path string

// TestPath returns the matching _test.go path for a source path.
func (p Path) TestPath() string {
	if p.IsTestPath() {
		return string(p)
	}
	return strings.TrimSuffix(string(p), ".go") + "_test.go"
}

// IsTestPath reports whether the path names a test file.
func (p Path) IsTestPath() bool {
	return strings.HasSuffix(string(p), "_test.go")
}
