{"command":"cd /workspace && cat > internal/goparser/goparser.go <<'EOF'
// Package goparser turns Go source files into the models consumed by the
// test renderer.
package goparser

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gotestsgen/internal/models"
)

// ErrEmptyFile is returned when the source file has no content.
var ErrEmptyFile = fmt.Errorf("file is empty")

// Result is the outcome of parsing a single source file.
type Result struct {
	Header *models.Header
	Funcs  []*models.Function
}

// Parser parses Go source files.
type Parser struct {
	Importer types.Importer
}

type parsedFile struct {
	path string
	src  []byte
	file *ast.File
}

// Parse parses srcPath. The files slice names the sibling files of the
// same directory that are consulted for type information and imports.
func (p *Parser) Parse(srcPath string, files []models.Path) (*Result, error) {
	b, err := os.ReadFile(srcPath)
	if err != nil {
		return nil, fmt.Errorf("os.ReadFile: %v", err)
	}
	if len(b) == 0 {
		return nil, ErrEmptyFile
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, srcPath, b, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("target parser.ParseFile(): %v", err)
	}
	target := &parsedFile{path: srcPath, src: b, file: f}

	var others []*parsedFile
	for _, fp := range files {
		of, err := parser.ParseFile(fset, string(fp), nil, parser.ParseComments)
		if err != nil {
			return nil, fmt.Errorf("other file parser.ParseFile: %v", err)
		}
		if of.Name.Name != f.Name.Name {
			continue
		}
		others = append(others, &parsedFile{path: string(fp), file: of})
	}

	all := append([]*parsedFile{target}, others...)
	ul := p.typeInfo(fset, all)

	hdr := &models.Header{
		Comments: headerComments(fset, f, b),
		Package:  f.Name.Name,
		Imports:  parseImports(f.Imports),
	}
	for _, o := range others {
		hdr.Imports = append(hdr.Imports, parseImports(o.file.Imports)...)
	}

	var funcs []*models.Function
	for _, d := range f.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Name.Name == "init" {
			continue
		}
		funcs = append(funcs, parseFunc(fset, fd, b, ul, all))
	}
	return &Result{Header: hdr, Funcs: funcs}, nil
}

// typeInfo type checks the files and indexes the underlying type of every
// type expression by its source representation.
func (p *Parser) typeInfo(fset *token.FileSet, files []*parsedFile) map[string]types.Type {
	imp := p.Importer
	if imp == nil {
		imp = importer.Default()
	}
	conf := &types.Config{
		Importer: imp,
		Error:    func(error) {},
	}
	info := &types.Info{Types: make(map[ast.Expr]types.TypeAndValue)}
	var fs []*ast.File
	for _, f := range files {
		fs = append(fs, f.file)
	}
	conf.Check("", fset, fs, info)

	ul := make(map[string]types.Type)
	for e, tv := range info.Types {
		if !tv.IsType() || tv.Type == nil {
			continue
		}
		if strings.Contains(tv.Type.String(), "invalid type") {
			continue
		}
		ul[types.ExprString(e)] = tv.Type.Underlying()
	}
	return ul
}

// headerComments collects the comment lines that precede the package
// clause, interleaved with blank-line markers.
func headerComments(fset *token.FileSet, f *ast.File, src []byte) []string {
	pkgOff := fset.Position(f.Package).Offset
	var out []string
	// consumed counts the bytes not covered by comments before an offset.
	gap := func(upto int, from int) int {
		n := 0
		for i := from; i < upto; i++ {
			n++
		}
		return n
	}
	prevEnd := 0
	plain := 0 // bytes outside comments so far
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			start := fset.Position(c.Pos()).Offset
			if start >= pkgOff {
				break
			}
			plain += gap(start, prevEnd)
			if n := plain - len(out); n > 0 {
				out = append(out, strings.Repeat("\n", n-1))
			}
			out = append(out, c.Text)
			prevEnd = fset.Position(c.End()).Offset
		}
	}
	if prevEnd < pkgOff {
		plain += gap(pkgOff, prevEnd)
	}
	if n := plain - len(out); n > 0 {
		out = append(out, strings.Repeat("\n", n-1))
	}
	return out
}

func parseImports(specs []*ast.ImportSpec) []*models.Import {
	var out []*models.Import
	for _, s := range specs {
		var name string
		if s.Name != nil {
			name = s.Name.Name
		}
		out = append(out, &models.Import{Name: name, Path: s.Path.Value})
	}
	return out
}

func parseFunc(fset *token.FileSet, fd *ast.FuncDecl, src []byte, ul map[string]types.Type, files []*parsedFile) *models.Function {
	fn := &models.Function{
		Name:       fd.Name.Name,
		IsExported: fd.Name.IsExported(),
	}
	if fd.Body != nil {
		start := fset.Position(fd.Body.Pos()).Offset
		end := fset.Position(fd.Body.End()).Offset
		if start >= 0 && end <= len(src) && start <= end {
			fn.Body = string(src[start:end])
		}
	}
	if fd.Type.TypeParams != nil {
		fn.TypeParams = parseTypeParams(fd.Type.TypeParams)
	}
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		recvField := parseFieldList(fd.Recv, ul, nil)[0]
		recv := &models.Receiver{Field: recvField}
		base := baseTypeName(fd.Recv.List[0].Type)
		if spec := findTypeSpec(files, base); spec != nil {
			if spec.TypeParams != nil {
				fn.TypeParams = parseTypeParams(spec.TypeParams)
			}
			if st, ok := spec.Type.(*ast.StructType); ok {
				var ts *types.Struct
				if t, ok := ul[recvField.Type.Value]; ok {
					ts, _ = t.(*types.Struct)
				}
				fields := parseFieldList(st.Fields, ul, ts)
				if !usesTypeParams(st, fn.TypeParams) {
					recv.Fields = fields
				}
			}
		}
		fn.Receiver = recv
	}
	fn.Parameters = parseFieldList(fd.Type.Params, ul, nil)
	results := parseFieldList(fd.Type.Results, ul, nil)
	idx := 0
	for _, r := range results {
		if r.Type.Value == "error" && !r.Type.IsStar && !r.Type.IsVariadic {
			fn.ReturnsError = true
			continue
		}
		r.Index = idx
		idx++
		fn.Results = append(fn.Results, r)
	}
	return fn
}

func parseTypeParams(fl *ast.FieldList) []*models.TypeParam {
	var out []*models.TypeParam
	for _, f := range fl.List {
		c := types.ExprString(f.Type)
		for _, n := range f.Names {
			out = append(out, &models.TypeParam{Name: n.Name, Constraint: c})
		}
	}
	return out
}

// usesTypeParams reports whether any field type of the struct mentions one
// of the type parameters.
func usesTypeParams(st *ast.StructType, tps []*models.TypeParam) bool {
	if len(tps) == 0 || st.Fields == nil {
		return false
	}
	names := make(map[string]bool, len(tps))
	for _, tp := range tps {
		names[tp.Name] = true
	}
	found := false
	for _, f := range st.Fields.List {
		ast.Inspect(f.Type, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok && names[id.Name] {
				found = true
			}
			return !found
		})
		if found {
			return true
		}
	}
	return false
}

func baseTypeName(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.StarExpr:
		return baseTypeName(v.X)
	case *ast.IndexExpr:
		return baseTypeName(v.X)
	case *ast.IndexListExpr:
		return baseTypeName(v.X)
	case *ast.Ident:
		return v.Name
	case *ast.ParenExpr:
		return baseTypeName(v.X)
	}
	return ""
}

func findTypeSpec(files []*parsedFile, name string) *ast.TypeSpec {
	if name == "" {
		return nil
	}
	for _, f := range files {
		for _, d := range f.file.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, s := range gd.Specs {
				ts, ok := s.(*ast.TypeSpec)
				if ok && ts.Name.Name == name {
					return ts
				}
			}
		}
	}
	return nil
}

func parseFieldList(fl *ast.FieldList, ul map[string]types.Type, st *types.Struct) []*models.Field {
	if fl == nil {
		return nil
	}
	var out []*models.Field
	i := 0
	for _, f := range fl.List {
		for _, mf := range expandField(f, ul) {
			mf.Index = i
			if st != nil && i < st.NumFields() {
				mf.Name = st.Field(i).Name()
			}
			out = append(out, mf)
			i++
		}
	}
	return out
}

func expandField(f *ast.Field, ul map[string]types.Type) []*models.Field {
	typ := parseExpr(f.Type, ul)
	if len(f.Names) == 0 {
		return []*models.Field{{Type: typ}}
	}
	var out []*models.Field
	for _, n := range f.Names {
		out = append(out, &models.Field{Name: n.Name, Type: typ})
	}
	return out
}

func parseExpr(e ast.Expr, ul map[string]types.Type) *models.Expression {
	switch v := e.(type) {
	case *ast.StarExpr:
		val := types.ExprString(v.X)
		return &models.Expression{Value: val, IsStar: true, Underlying: underlying(val, ul)}
	case *ast.Ellipsis:
		inner := parseExpr(v.Elt, ul)
		return &models.Expression{
			Value:      inner.Value,
			IsStar:     inner.IsStar,
			IsVariadic: true,
			Underlying: underlying(inner.Value, ul),
		}
	default:
		val := types.ExprString(e)
		return &models.Expression{
			Value:      val,
			IsWriter:   val == "io.Writer",
			Underlying: underlying(val, ul),
		}
	}
}

func underlying(val string, ul map[string]types.Type) string {
	if t, ok := ul[val]; ok && t != nil {
		return t.String()
	}
	return ""
}

// SiblingFiles lists the non-test Go files living next to path, sorted.
func SiblingFiles(path string) ([]models.Path, error) {
	dir := filepath.Dir(path)
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var out []models.Path
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		n := e.Name()
		if !strings.HasSuffix(n, ".go") || strings.HasSuffix(n, "_test.go") {
			continue
		}
		out = append(out, models.Path(filepath.Join(dir, n)))
	}
	sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	return out, nil
}
