// Package input resolves command line path arguments to Go source files.
package input

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"gotestsgen/internal/models"
)

const recursiveSuffix = "/..."

// Files returns the Go source files denoted by srcPath. A path ending in
// "/..." is walked recursively.
func Files(srcPath string) ([]models.Path, error) {
	recursive := false
	if strings.HasSuffix(srcPath, recursiveSuffix) {
		recursive = true
		srcPath = strings.TrimSuffix(srcPath, recursiveSuffix)
	} else if srcPath == "..." {
		recursive = true
		srcPath = "."
	}
	abs, err := filepath.Abs(srcPath)
	if err != nil {
		return nil, fmt.Errorf("filepath.Abs: %v\n", err)
	}
	if recursive {
		return walk(abs)
	}
	fi, err := os.Stat(abs)
	if err != nil {
		return nil, fmt.Errorf("os.Stat: %v\n", err)
	}
	if fi.IsDir() {
		return dirFiles(abs)
	}
	if !isGoFile(abs) {
		return nil, fmt.Errorf("no Go source files found at %v", abs)
	}
	return []models.Path{models.Path(abs)}, nil
}

func walk(root string) ([]models.Path, error) {
	found := make(map[string]struct{})
	err := filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if p != root && strings.HasPrefix(info.Name(), ".") {
				return filepath.SkipDir
			}
			return nil
		}
		if isGoFile(p) && !strings.HasSuffix(p, "_test.go") {
			found[p] = struct{}{}
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("filepath.Walk: %v\n", err)
	}
	var out []models.Path
	for p := range found {
		out = append(out, models.Path(p))
	}
	return out, nil
}

func dirFiles(dir string) ([]models.Path, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("ioutil.ReadDir: %v\n", err)
	}
	var out []models.Path
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		n := e.Name()
		if !isGoFile(n) || strings.HasSuffix(n, "_test.go") {
			continue
		}
		out = append(out, models.Path(filepath.Join(dir, n)))
	}
	return out, nil
}

func isGoFile(p string) bool {
	return strings.HasSuffix(p, ".go")
}
EOF
echo ok"}

