// Package output renders test files and formats them.
package output

import (
	"bytes"
	"fmt"
	"os"

	"golang.org/x/tools/imports"

	"gotestsgen/internal/ai"
	"gotestsgen/internal/models"
	"gotestsgen/internal/render"
)

// Options configure the rendering of a test file.
type Options struct {
	PrintInputs    bool
	Subtests       bool
	Parallel       bool
	Named          bool
	UseGoCmp       bool
	Template       string
	TemplateDir    string
	TemplateParams map[string]interface{}

	AI *ai.Config
}

// Process renders the header and the given functions and returns the
// formatted Go source.
func Process(head *models.Header, funcs []*models.Function, opt *Options) ([]byte, error) {
	r := render.New()
	if opt.TemplateDir != "" {
		if err := r.LoadCustomTemplates(opt.TemplateDir); err != nil {
			return nil, fmt.Errorf("loading custom templates: %v", err)
		}
	} else if opt.Template != "" {
		if err := r.LoadCustomTemplatesName(opt.Template); err != nil {
			return nil, fmt.Errorf("loading custom templates of name: %v", err)
		}
	}

	var gen *ai.Generator
	if opt.AI != nil && opt.AI.Enabled {
		var err error
		gen, err = ai.NewGenerator(opt.AI)
		if err != nil {
			return nil, err
		}
	}

	tf, err := os.CreateTemp("", "gotests_")
	if err != nil {
		return nil, fmt.Errorf("ioutil.TempFile: %v", err)
	}
	defer tf.Close()
	defer os.Remove(tf.Name())

	buf := &bytes.Buffer{}
	if err := r.Header(buf, head); err != nil {
		return nil, fmt.Errorf("render.Header: %v", err)
	}
	for _, fn := range funcs {
		ro := render.Options{
			PrintInputs:    opt.PrintInputs,
			Subtests:       opt.Subtests,
			Parallel:       opt.Parallel,
			Named:          opt.Named,
			UseGoCmp:       opt.UseGoCmp,
			TemplateParams: opt.TemplateParams,
		}
		if gen != nil {
			ro.AIGeneratedCases = gen.Cases(fn)
		}
		if err := r.TestFunction(buf, fn, ro); err != nil {
			return nil, fmt.Errorf("render.TestFunction: %v", err)
		}
	}
	out, err := imports.Process(tf.Name(), buf.Bytes(), nil)
	if err != nil {
		return nil, fmt.Errorf("imports.Process: %v", err)
	}
	return out, nil
}
EOF
