	files, err := input.Files(srcPath)
	if err != nil {
		return nil, fmt.Errorf("input.Files: %v", err)
	}
	var results []*GeneratedTest
	for _, src := range files {
		if src.IsTestPath() {
			continue
		}
		siblings, err := goparser.SiblingFiles(string(src))
		if err != nil {
			return nil, fmt.Errorf("input.Files: %v", err)
		}
		gt, err := generateTest(src, siblings, opt, outOpt)
		if err != nil {
			return nil, err
		}
		if gt != nil {
			results = append(results, gt)
		}
	}
	return results, nil
}

func generateTest(src models.Path, files []models.Path, opt *Options, outOpt *output.Options) (*GeneratedTest, error) {
	p := &goparser.Parser{}
	sr, err := p.Parse(string(src), files)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse source file: %v", err)
	}
	head := sr.Header
	head.Code = nil

	testPath := src.TestPath()
	var existing map[string]bool
	if _, err := os.Stat(testPath); err == nil {
		tr, err := p.Parse(testPath, nil)
		if err != nil {
			return nil, fmt.Errorf("Parser.Parse test file: %v", err)
		}
		existing = make(map[string]bool)
		for _, f := range tr.Funcs {
			existing[f.Name] = true
		}
		th := tr.Header
		th.Imports = append(th.Imports, head.Imports...)
		head = th
	}

	funcs := selectFunctions(sr.Funcs, opt, existing)
	if len(funcs) == 0 {
		return nil, nil
	}
