	if err != nil {
		return nil, fmt.Errorf("output.Process: %v", err)
	}
	return &GeneratedTest{Path: testPath, Functions: funcs, Output: out}, nil
}

func selectFunctions(funcs []*models.Function, opt *Options, existing map[string]bool) []*models.Function {
	var out []*models.Function
	for _, f := range funcs {
		if opt.Exclude != nil && (opt.Exclude.MatchString(f.Name) || opt.Exclude.MatchString(f.FullName())) {
