// Command gotests generates table-driven Go tests from source files.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"go/build"
	"os"
	"regexp"

	"gotestsgen/internal/ai"
	"gotestsgen/internal/output"
)

const (
	versionString = "v0.0.0-20260611191915-db3bc27e8c01"
	goVersion     = "go1.24.5"
