	buildTime     = "2026-06-11T19:19:15Z"
)

var (
	onlyFuncs          = flag.String("only", "", `regexp. generate tests for functions and methods that match only. Takes precedence over -all`)
	exclFuncs          = flag.String("excl", "", `regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all`)
	exportedFuncs      = flag.Bool("exported", false, `generate tests for exported functions and methods. Takes precedence over -only and -all`)
	allFuncs           = flag.Bool("all", false, "generate tests for all functions and methods")
	printInputs        = flag.Bool("i", false, "print test inputs in error messages")
	writeOutput        = flag.Bool("w", false, "write output to (test) files instead of stdout")
	templateDir        = flag.String("template_dir", "", `optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR`)
	template           = flag.String("template", "", `optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE`)
	templateParamsPath = flag.String("template_params_file", "", "read external parameters to template by json with file")
	templateParams     = flag.String("template_params", "", "read external parameters to template by json with stdin")
	nosubtests         = flag.Bool("nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
	parallel           = flag.Bool("parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
	named              = flag.Bool("named", false, "switch table tests from using slice to map (with test name for the key)")
	useGoCmp           = flag.Bool("use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
	showVersion        = flag.Bool("version", false, "print version information and exit")
	aiEnabled          = flag.Bool("ai", false, "generate test cases using AI (requires Ollama)")
	aiModel            = flag.String("ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
	aiEndpoint         = flag.String("ai-endpoint", "http://localhost:11434", "Ollama API endpoint")
	aiMinCases         = flag.Int("ai-min-cases", 3, "minimum number of test cases to generate with AI")
	aiMaxCases         = flag.Int("ai-max-cases", 10, "maximum number of test cases to generate with AI")
)

func main() {
	// Only honour an explicitly configured GOROOT when resolving standard
	// library packages for type information.
	build.Default.GOROOT = os.Getenv("GOROOT")

	flag.Parse()
	if *showVersion {
		fmt.Printf("gotests %s\n", versionString)
		fmt.Printf("Go version: %s\n", goVersion)
		fmt.Printf("Git commit: %s\n", gitCommit)
		fmt.Printf("Build time: %s\n", buildTime)
		return
	}
	if *aiEnabled {
		fmt.Fprintf(os.Stderr, "⚠️  WARNING: Function source code will be sent to AI provider at %s\n", *aiEndpoint)
		fmt.Fprintf(os.Stderr, "   Ensure your code does not contain secrets or sensitive information.\n\n")
	}
	if *onlyFuncs == "" && *exclFuncs == "" && !*exportedFuncs && !*allFuncs {
		fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
		return
	}
	opt := &Options{
		Exported:    *exportedFuncs,
		PrintInputs: *printInputs,
		Subtests:    !*nosubtests,
		Parallel:    *parallel,
		Named:       *named,
		UseGoCmp:    *useGoCmp,
	}
	if *onlyFuncs != "" {
		re, err := regexp.Compile(*onlyFuncs)
		if err != nil {
			fmt.Printf("Invalid -only regex: %s\n", err)
			return
		}
		opt.Only = re
	}
	if *exclFuncs != "" {
		re, err := regexp.Compile(*exclFuncs)
		if err != nil {
			fmt.Printf("Invalid -excl regex: %s\n", err)
			return
		}
		opt.Exclude = re
	}

	params := map[string]interface{}{}
	if *templateParams != "" {
		if err := json.Unmarshal([]byte(*templateParams), &params); err != nil {
			fmt.Printf("Failed to unmarshal template_params JSON: %v", err)
			return
		}
	}
	if *templateParamsPath != "" {
		b, err := os.ReadFile(*templateParamsPath)
		if err != nil {
			fmt.Printf("Failed to read from %s ,err %v", *templateParamsPath, err)
			return
		}
		if err := json.Unmarshal(b, &params); err != nil {
			fmt.Printf("Failed to umarshal %s er %v", *templateParamsPath, err)
			return
		}
	}

	tmplDir := *templateDir
	if tmplDir == "" {
		tmplDir = os.Getenv("GOTESTS_TEMPLATE_DIR")
	}
	tmpl := *template
	if tmpl == "" {
		tmpl = os.Getenv("GOTESTS_TEMPLATE")
	}

	outOpt := &output.Options{
		PrintInputs:    *printInputs,
		Subtests:       !*nosubtests,
		Parallel:       *parallel,
		Named:          *named,
		UseGoCmp:       *useGoCmp,
		Template:       tmpl,
		TemplateDir:    tmplDir,
		TemplateParams: params,
		AI: &ai.Config{
			Enabled:  *aiEnabled,
			Endpoint: *aiEndpoint,
			Model:    *aiModel,
			MinCases: *aiMinCases,
			MaxCases: *aiMaxCases,
		},
	}

	if len(flag.Args()) == 0 {
		fmt.Println("Please specify a file or directory containing the source")
		return
	}
	for _, path := range flag.Args() {
		generated, err := GenerateTests(path, opt, outOpt)
		if err != nil {
			fmt.Println(err.Error())
			continue
		}
		if len(generated) == 0 {
			fmt.Printf("No tests generated for %v\n", path)
			continue
		}
		for _, t := range generated {
			if *writeOutput {
				if err := os.WriteFile(t.Path, t.Output, 0644); err != nil {
					fmt.Println(err)
					continue
				}
			}
			for _, f := range t.Functions {
				fmt.Printf("Generated %v\n", f.TestName())
			}
			if !*writeOutput {
				fmt.Print(string(t.Output))
			}
		}
	}
}
