{"command":"cd /workspace && cat > internal/ai/ai.go <<'EOF'
// Package ai generates table-driven test cases with the help of a local
// LLM served by Ollama.
package ai

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"

	"gotestsgen/internal/models"
)

// Config holds the AI related command line settings.
type Config struct {
	Enabled  bool
	Endpoint string
	Model    string
	MinCases int
	MaxCases int
}

// TestCase is a single generated table entry.
type TestCase struct {
	Name        string
	Description string
	Args        map[string]string
	Want        map[string]string
	WantErr     bool
}

const (
	providerName = "ollama"
	maxAttempts  = 3
)

// Generator produces test cases for functions.
type Generator struct {
	cfg    *Config
	client *http.Client
}

// NewGenerator validates the configuration and checks that the provider is
// reachable.
func NewGenerator(cfg *Config) (*Generator, error) {
	if err := validateEndpoint(cfg.Endpoint); err != nil {
		return nil, fmt.Errorf("failed to create AI provider: %v", err)
	}
	g := &Generator{cfg: cfg, client: &http.Client{Timeout: 5 * time.Minute}}
	if !g.available() {
		return nil, fmt.Errorf("AI provider %s is not available - ensure Ollama is running at %s", providerName, cfg.Endpoint)
	}
	return g, nil
}

func validateEndpoint(endpoint string) error {
	u, err := url.Parse(endpoint)
	if err != nil {
		return fmt.Errorf("invalid endpoint: %v", err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("invalid endpoint: invalid URL scheme %q: only http and https are allowed", u.Scheme)
	}
	if u.Host == "" {
		return fmt.Errorf("invalid endpoint: missing host")
	}
	return nil
}

func (g *Generator) available() bool {
	c := &http.Client{Timeout: 10 * time.Second}
	resp, err := c.Get(strings.TrimRight(g.cfg.Endpoint, "/") + "/api/tags")
	if err != nil {
		return false
	}
	defer resp.Body.Close()
	io.Copy(io.Discard, resp.Body)
	return resp.StatusCode == http.StatusOK
}

// Cases asks the provider for test cases of fn. Failures are reported as
// warnings and yield no cases.
func (g *Generator) Cases(fn *models.Function) []interface{} {
	cases, err := g.generate(fn)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to generate AI test cases for %s: %v\n", fn.Name, err)
		return nil
	}
	out := make([]interface{}, 0, len(cases))
	for _, c := range cases {
		out = append(out, c)
	}
	return out
}

func (g *Generator) generate(fn *models.Function) ([]TestCase, error) {
	base := buildPrompt(fn, g.cfg)
	var lastErr error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		prompt := base
		if lastErr != nil {
			prompt += fmt.Sprintf("PREVIOUS ATTEMPT FAILED:\n%v\n\nPlease fix the above issue.\n\n", lastErr)
		}
		prompt += scaffoldInstruction(fn)
		resp, err := g.complete(prompt)
		if err != nil {
			lastErr = err
			continue
		}
		cases, err := parseCases(resp, fn)
		if err != nil {
			lastErr = fmt.Errorf("%v\n\nLLM Response:\n%s", err, resp)
			continue
		}
		if err := validateCases(cases, g.cfg); err != nil {
			lastErr = fmt.Errorf("%v\n\nLLM Response:\n%s", err, resp)
			continue
		}
		if len(cases) > g.cfg.MaxCases && g.cfg.MaxCases > 0 {
			cases = cases[:g.cfg.MaxCases]
		}
		return cases, nil
	}
	return nil, fmt.Errorf("failed after %d attempts: %v", maxAttempts, lastErr)
}

type generateRequest struct {
	Model   string                 `json:"model"`
	Options map[string]interface{} `json:"options"`
	Prompt  string                 `json:"prompt"`
	Stream  bool                   `json:"stream"`
}

type generateResponse struct {
	Response string `json:"response"`
	Error    string `json:"error"`
}

func (g *Generator) complete(prompt string) (string, error) {
	body, err := json.Marshal(generateRequest{
		Model:   g.cfg.Model,
		Options: map[string]interface{}{"seed": 42, "temperature": 0},
		Prompt:  prompt,
		Stream:  false,
	})
	if err != nil {
		return "", fmt.Errorf("marshal request: %v", err)
	}
	resp, err := g.client.Post(strings.TrimRight(g.cfg.Endpoint, "/")+"/api/generate", "application/json", bytes.NewReader(body))
	if err != nil {
		return "", fmt.Errorf("ollama request failed: %v", err)
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("read response: %v", err)
	}
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("ollama returned %d: %s", resp.StatusCode, strings.TrimSpace(string(data)))
	}
	var gr generateResponse
	if err := json.Unmarshal(data, &gr); err != nil {
		return "", fmt.Errorf("decode response: %v", err)
	}
	if gr.Error != "" {
		return "", fmt.Errorf("ollama error: %s", gr.Error)
	}
	return gr.Response, nil
}

// signature renders the function header followed by its body.
func signature(fn *models.Function) string {
	var b strings.Builder
	b.WriteString("func ")
	if fn.Receiver != nil {
		b.WriteString("(")
		if fn.Receiver.Name != "" {
			b.WriteString(fn.Receiver.Name + " ")
		}
		b.WriteString(fn.Receiver.Type.String())
		b.WriteString(") ")
	}
	b.WriteString(fn.Name)
	b.WriteString("(")
	for i, p := range fn.Parameters {
		if i > 0 {
			b.WriteString(", ")
		}
		if p.Name != "" {
			b.WriteString(p.Name + " ")
		}
		if p.Type.IsVariadic {
			v := p.Type.Value
			if p.Type.IsStar {
				v = "*" + v
			}
			b.WriteString("..." + v)
		} else {
			b.WriteString(p.Type.String())
		}
	}
	b.WriteString(")")
	var results []string
	for _, r := range fn.Results {
		if r.Name != "" {
			results = append(results, r.Name+" "+r.Type.String())
		} else {
			results = append(results, r.Type.String())
		}
	}
	if fn.ReturnsError {
		results = append(results, "error")
	}
	switch len(results) {
	case 0:
	case 1:
		b.WriteString(" " + results[0])
	default:
		b.WriteString(" (" + strings.Join(results, ", ") + ")")
	}
	if fn.Body != "" {
		b.WriteString(" " + fn.Body)
	}
	return b.String()
}

// scaffold renders the table declaration as it appears in the test.
func scaffold(fn *models.Function) string {
	var b strings.Builder
	b.WriteString("tests := []struct {\n")
	b.WriteString("\tname string\n")
	if fn.Receiver != nil && fn.Receiver.IsStruct() && len(fn.Receiver.Fields) > 0 {
		b.WriteString("\tfields fields\n")
	}
	if len(fn.TestParameters()) > 0 {
		b.WriteString("\targs args\n")
	}
	for _, r := range fn.TestResults() {
		b.WriteString("\t" + wantName(r) + " " + r.Type.String() + "\n")
	}
	if fn.ReturnsError {
		b.WriteString("\twantErr bool\n")
	}
	b.WriteString("} {\n\t// TODO: Add test cases.\n}")
	return b.String()
}

func example(fn *models.Function) string {
	var b strings.Builder
	b.WriteString("{\n")
	b.WriteString("    name: \"descriptive test name\",\n")
	if fn.Receiver != nil && fn.Receiver.IsStruct() && len(fn.Receiver.Fields) > 0 {
