// extractCode pulls the contents of the first fenced code block, or returns
// the whole text when no fence is present.
func extractCode(resp string) string {
	s := resp
	if i := strings.Index(s, "```"); i >= 0 {
		s = s[i+3:]
		if nl := strings.Index(s, "\n"); nl >= 0 {
			first := strings.TrimSpace(s[:nl])
			if first == "" || first == "go" || first == "golang" {
				s = s[nl+1:]
			}
		}
		if j := strings.Index(s, "```"); j >= 0 {
			s = s[:j]
		}
	}
	return strings.TrimSpace(s)
}

const wrapperHead = "package main\n\nimport (\n\t\"testing\"\n)\n\nfunc TestGenerated(t *testing.T) {\n\ttests := []struct{}{\n"

func parseCases(resp string, fn *models.Function) ([]TestCase, error) {
	code := extractCode(resp)
	src := wrapperHead + code + "\n\t}\n\t_ = tests\n}\n"
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "test.go", src, 0)
	if err != nil {
		return nil, fmt.Errorf("parse Go test cases: parse Go code: %v", err)
	}
	var lit *ast.CompositeLit
	ast.Inspect(f, func(n ast.Node) bool {
		if lit != nil {
			return false
		}
		if as, ok := n.(*ast.AssignStmt); ok && len(as.Rhs) == 1 {
			if cl, ok := as.Rhs[0].(*ast.CompositeLit); ok {
				lit = cl
				return false
			}
		}
		return true
	})
	if lit == nil {
		return nil, fmt.Errorf("parse Go test cases: no test case array found")
	}
	var cases []TestCase
	for _, elt := range lit.Elts {
		cl, ok := elt.(*ast.CompositeLit)
		if !ok {
			return nil, fmt.Errorf("parse Go test cases: unexpected element %s", exprText(src, fset, elt))
		}
		tc := TestCase{Args: map[string]string{}, Want: map[string]string{}}
		for _, e := range cl.Elts {
			kv, ok := e.(*ast.KeyValueExpr)
			if !ok {
				return nil, fmt.Errorf("parse Go test cases: test case fields must be named")
			}
			key := exprText(src, fset, kv.Key)
			switch {
			case key == "name":
				if bl, ok := kv.Value.(*ast.BasicLit); ok && bl.Kind == token.STRING {
					if s, err := strconv.Unquote(bl.Value); err == nil {
						tc.Name = s
						continue
					}
				}
				tc.Name = exprText(src, fset, kv.Value)
			case key == "args" || key == "fields":
				inner, ok := kv.Value.(*ast.CompositeLit)
				if !ok {
					return nil, fmt.Errorf("parse Go test cases: %s must be a composite literal", key)
				}
				for _, ie := range inner.Elts {
					ikv, ok := ie.(*ast.KeyValueExpr)
					if !ok {
						return nil, fmt.Errorf("parse Go test cases: %s fields must be named", key)
					}
					tc.Args[exprText(src, fset, ikv.Key)] = exprText(src, fset, ikv.Value)
				}
			case key == "wantErr":
				tc.WantErr = exprText(src, fset, kv.Value) == "true"
			case strings.HasPrefix(key, "want"):
				tc.Want[key] = exprText(src, fset, kv.Value)
			default:
				tc.Args[key] = exprText(src, fset, kv.Value)
			}
		}
		cases = append(cases, tc)
	}
	if len(cases) == 0 {
		return nil, fmt.Errorf("parse Go test cases: no test cases found")
	}
	return cases, nil
}

func exprText(src string, fset *token.FileSet, e ast.Expr) string {
	start := fset.Position(e.Pos()).Offset
	end := fset.Position(e.End()).Offset
	if start < 0 || end > len(src) || start > end {
		return ""
	}
	return src[start:end]
}

func validateCases(cases []TestCase, cfg *Config) error {
	if cfg.MinCases > 0 && len(cases) < cfg.MinCases {
		return fmt.Errorf("generated %d test cases, but at least %d are required", len(cases), cfg.MinCases)
	}
	seen := map[string]int{}
	for i, c := range cases {
		keys := make([]string, 0, len(c.Args))
		for k := range c.Args {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var sig strings.Builder
		for _, k := range keys {
			sig.WriteString(k + "=" + c.Args[k] + ";")
		}
		if sig.Len() == 0 {
			continue
		}
		if j, dup := seen[sig.String()]; dup {
			return fmt.Errorf("test cases %d and %d have identical inputs (%s); every test case must use different values", j+1, i+1, strings.TrimSuffix(sig.String(), ";"))
		}
		seen[sig.String()] = i
	}
	return nil
}

func fieldName(f *models.Field) string {
	if f.IsNamed() {
		return f.Name
	}
	return f.Type.String()
}

func paramName(f *models.Field) string {
	if f.IsNamed() {
		return f.Name
	}
	return fmt.Sprintf("in%d", f.Index)
}

func wantName(f *models.Field) string {
	if f.IsNamed() {
		r := []rune(f.Name)
		return "want" + strings.ToUpper(string(r[0])) + string(r[1:])
	}
	if f.Index == 0 {
		return "want"
	}
	return fmt.Sprintf("want%d", f.Index)
}
